cat > s4.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(1000);
await p.goto('http://127.0.0.1:54569/settings');
await p.waitForTimeout(500);
const f = p.frames().find(f => f.url().includes('/widgets/notifications'));
const h = await f.evaluateHandle(() => document.querySelector('notify-settings').shadowRoot);
await f.evaluate(() => { const r = document.querySelector('notify-settings').shadowRoot; const i = r.getElementById('th'); i.value='485'; i.dispatchEvent(new Event('input',{bubbles:true})); r.getElementById('sw').click(); });
await f.evaluate(() => document.querySelector('notify-settings').shadowRoot.getElementById('sv').click());
await p.waitForTimeout(800);
console.log(await f.evaluate(() => { const r = document.querySelector('notify-settings').shadowRoot; return [r.getElementById('th').value, r.getElementById('sw').textContent, r.getElementById('ok').textContent]; }));
const g = await p.request.get('http://127.0.0.1:54569/api/settings', {headers:{'x-ui':'1'}}).catch(e=>null);
if (g) console.log(await g.text());
await b.close();
EOF
node s4.mjs
